const SESSION_DAYS=90;

// ═══ Durable Object : un seul coffre pour tout le parc (cohérence forte, opérations sérialisées)
export class Store{
  constructor(state,env){this.state=state;this.storage=state.storage;this.env=env;}

  async getData(){
    const meta=await this.storage.get('data:meta');if(!meta)return null;
    const parts=[];for(let i=0;i<meta.chunks;i++)parts.push(await this.storage.get('data:'+i));
    const bytes=new Uint8Array(meta.size);let off=0;parts.forEach(p=>{const u=new Uint8Array(p);bytes.set(u,off);off+=u.length;});
    const text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
    return JSON.parse(text);
  }
  async putData(obj){
    const gz=new Uint8Array(await new Response(new Blob([JSON.stringify(obj)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
    const CH=1000000,chunks=Math.ceil(gz.length/CH)||1,old=await this.storage.get('data:meta');
    const put={};for(let i=0;i<chunks;i++)put['data:'+i]=gz.slice(i*CH,(i+1)*CH).buffer;
    const rev=((old&&old.rev)||0)+1;
    put['data:meta']={chunks,size:gz.length,rev,at:Date.now()};
    await this.storage.put(put);
    if(old&&old.chunks>chunks){const del=[];for(let i=chunks;i<old.chunks;i++)del.push('data:'+i);await this.storage.delete(del);}
    return rev;
  }
  async backup(){ // copie quotidienne (7 jours glissants)
    const meta=await this.storage.get('data:meta');if(!meta)return;
    const day=new Date().toISOString().slice(0,10),last=await this.storage.get('bk:last');
    if(last===day)return;
    const cur=await this.getData();
    const gz=new Uint8Array(await new Response(new Blob([JSON.stringify(cur)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
    if(gz.length<1900000)await this.storage.put('bk:'+day,gz.buffer);
    await this.storage.put('bk:last',day);
    const keys=[...(await this.storage.list({prefix:'bk:20'})).keys()].sort();
    if(keys.length>7)await this.storage.delete(keys.slice(0,keys.length-7));
  }


  async mailBackup(origine){ // copie complète des données envoyée par e-mail (hors serveur)
    const cfg=(await this.storage.get('mail:cfg'))||null,st={at:Date.now(),origine,ok:false};
    try{
      if(!cfg||!cfg.apiKey)throw new Error('envoi d\'e-mails non configuré (Paramètres → E-mails)');
      const d=await this.getData();if(!d)throw new Error('aucune donnée');
      const day=new Date().toISOString().slice(0,10),json=enc.encode(JSON.stringify(d));
      const zip=await zipOne('immogest_sauvegarde_'+day+'.json',json);
      if(zip.length>9000000)throw new Error('sauvegarde trop lourde pour un e-mail ('+Math.round(zip.length/1e6)+' Mo)');
      const to=cfg.backupTo||cfg.replyTo||cfg.senderEmail;st.to=to;st.size=zip.length;
      const nb=k=>Array.isArray(d[k])?d[k].length:0;
      const text='Sauvegarde ImmoGest Pro du '+new Date().toLocaleDateString('fr-FR',{timeZone:'Europe/Paris'})+' ('+(origine==='auto'?'envoi automatique hebdomadaire':'envoi manuel')+').\n\n'+
        'Contenu : '+nb('scis')+' SCI, '+nb('batiments')+' bâtiments, '+nb('logements')+' lots, '+nb('locataires')+' locataires, '+nb('paiements')+' paiements, '+nb('prets')+' prêts, '+nb('projets')+' projets.\n'+
        'Les documents et photos du coffre partent dans des e-mails séparés (seulement les nouveaux).\n\nPour restaurer : décompresser le fichier, puis appli → Paramètres → Appareils et sauvegardes → « Restaurer depuis un fichier ».\nConserver cet e-mail : il contient les coordonnées des locataires.';
      const payload={sender:{email:cfg.senderEmail,name:cfg.senderName||'ImmoGest Pro'},to:[{email:to}],subject:'Sauvegarde ImmoGest — '+day,textContent:text,attachment:[{name:'immogest_sauvegarde_'+day+'.zip',content:bytesToB64(zip)}]};
      const r=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{'api-key':cfg.apiKey,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});
      const t=await r.text();if(!r.ok){let e={};try{e=JSON.parse(t);}catch(x){}throw new Error('Brevo : '+(e.message||('erreur '+r.status)));}
      st.ok=true;
    }catch(e){st.error=e.message;}
    await this.storage.put('bkmail:last',st);return st;
  }

  async brevoSend(cfg,to,subject,text,attName,bytes){
    const payload={sender:{email:cfg.senderEmail,name:cfg.senderName||'ImmoGest Pro'},to:[{email:to}],subject,textContent:text,attachment:[{name:attName,content:bytesToB64(bytes)}]};
    const r=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{'api-key':cfg.apiKey,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});
    const t=await r.text();if(!r.ok){let e={};try{e=JSON.parse(t);}catch(x){}throw new Error('Brevo : '+(e.message||('erreur '+r.status)));}
  }
  async mailFiles(maxMails){ // documents et photos du coffre : envoi progressif, seulement ce qui n'a jamais été envoyé
    const cfg=(await this.storage.get('mail:cfg'))||null,LIM=7000000;
    const st={at:Date.now(),ok:false,emails:0,fichiers:0,restants:0,trop_gros:[]};
    try{
      if(!cfg||!cfg.apiKey)throw new Error('envoi d\'e-mails non configuré');
      const to=cfg.backupTo||cfg.replyTo||cfg.senderEmail,sent=(await this.storage.get('bkmail:sent'))||{};
      const d=(await this.getData())||{},bat=id=>((d.batiments||[]).find(b=>b.id===id)||{}).nom||'',lot=id=>((d.logements||[]).find(l=>l.id===id)||{}).ref||'';
      const metas=[...(await this.storage.list({prefix:'fm:'})).values()].sort((a,b)=>a.created-b.created);
      metas.forEach(m=>{if(m.size>LIM&&!sent[m.id])st.trop_gros.push(m.name+' ('+Math.round(m.size/1e6)+' Mo)');});
      let pending=metas.filter(m=>!sent[m.id]&&m.size<=LIM),day=new Date().toISOString().slice(0,10),part=0;
      const used={};
      while(pending.length&&st.emails<maxMails){
        const batch=[];let tot=0;while(pending.length&&tot+pending[0].size<=LIM){const m=pending.shift();batch.push(m);tot+=m.size;}
        const entries=[];for(const m of batch){let base=safeZipName(bat(m.batId)||'Sans bâtiment')+'/'+safeZipName(m.cat||'Autre')+'/'+(m.logId&&lot(m.logId)?safeZipName(lot(m.logId))+' - ':'')+safeZipName(m.name);let n=base,k=2;while(used[n]){n=base.replace(/(\.[^.\/]+)?$/,' ('+k+++')$1');}used[n]=1;entries.push({name:n,bytes:await this.fileBytes(m)});}
        part++;const zip=await zipMany(entries);
        await this.brevoSend(cfg,to,'Sauvegarde ImmoGest — documents '+day+' (partie '+part+')','Documents et photos du coffre ImmoGest ajoutés depuis le dernier envoi : '+batch.length+' fichier(s).\nClassement dans le ZIP : bâtiment / catégorie / fichier.\nConserver cet e-mail : il peut contenir des pièces personnelles des locataires.','immogest_documents_'+day+'_'+part+'.zip',zip);
        batch.forEach(m=>{sent[m.id]=1;});await this.storage.put('bkmail:sent',sent);st.emails++;st.fichiers+=batch.length;
      }
      st.restants=pending.length;st.ok=true;
    }catch(e){st.error=e.message;}
    await this.storage.put('bkfiles:last',st);return st;
  }
  async restoreData(nd){ // remplace toutes les données par une sauvegarde ; la version actuelle est gardée de côté
    if(!nd||typeof nd!=='object'||!Array.isArray(nd.batiments)||!Array.isArray(nd.logements))throw new Error('fichier de sauvegarde ImmoGest invalide');
    const cur=(await this.getData())||{},now=Date.now(),tag='bkpre:'+new Date().toISOString();
    const gz=new Uint8Array(await new Response(new Blob([JSON.stringify(cur)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
    if(gz.length<1900000)await this.storage.put(tag,gz.buffer);
    const pre=[...(await this.storage.list({prefix:'bkpre:'})).keys()].sort();if(pre.length>3)await this.storage.delete(pre.slice(0,pre.length-3));
    const tomb=Object.assign({},cur.tomb||{},nd.tomb||{}),out={tomb};
    ARR_KEYS.forEach(k=>{const arr=(Array.isArray(nd[k])?nd[k]:[]).filter(r=>r&&r.id).map(r=>Object.assign({},r,{_ts:now})),ids=new Set(arr.map(r=>r.id));
      arr.forEach(r=>{delete tomb[r.id];});(cur[k]||[]).forEach(r=>{if(r&&r.id&&!ids.has(r.id))tomb[r.id]=now;});out[k]=arr;});
    ['settings','notes'].forEach(k=>{out[k]=Object.assign({},nd[k]||cur[k]||{},{_ts:now});});
    const rev=await this.putData(out);
    return {ok:true,rev,annulable:tag,compte:{batiments:out.batiments.length,logements:out.logements.length,locataires:out.locataires.length,paiements:out.paiements.length}};
  }

  async newSession(role,label,extra){
    const token=b64u(rand(32)),th=hex(await sha256(token));
    const rec=Object.assign({role,label:(label||'').slice(0,80),created:Date.now(),exp:Date.now()+SESSION_DAYS*86400000,seen:Date.now()},extra||{});
    if(rec.hardExp)rec.exp=Math.min(rec.exp,rec.hardExp);
    await this.storage.put('sess:'+th,rec);
    return token;
  }
  async session(req){
    const a=req.headers.get('Authorization')||'';const m=a.match(/^Bearer (.+)$/);if(!m)return null;
    const th=hex(await sha256(m[1]));const s=await this.storage.get('sess:'+th);
    if(!s||s.exp<Date.now())return null;
    if(s.shareId&&!(await this.storage.get('share:'+s.shareId))){await this.storage.delete('sess:'+th);return null;}
    if(Date.now()-s.seen>3600000){s.seen=Date.now();s.exp=Date.now()+SESSION_DAYS*86400000;if(s.hardExp)s.exp=Math.min(s.exp,s.hardExp);await this.storage.put('sess:'+th,s);}
    s.key=th;return s;
  }
  async lockState(){return (await this.storage.get('auth:fails'))||{n:0,until:0};}
  async registerFail(){
    const f=await this.lockState();f.n++;
    if(f.n>=15)f.until=Date.now()+24*3600000;else if(f.n>=10)f.until=Date.now()+3600000;else if(f.n>=5)f.until=Date.now()+15*60000;
    await this.storage.put('auth:fails',f);return f;
  }

  async fetch(req){
    const url=new URL(req.url),p=url.pathname,method=req.method;
    const origin=url.origin,rpId=url.hostname;
    if(p==='/__cron/backup'){const a=await this.mailBackup('auto');const f=a.ok?await this.mailFiles(15):null;return json({donnees:a,documents:f});}
    if(p==='/mcp'||p.startsWith('/oauth/')||p.startsWith('/.well-known/'))return this.mcpRoute(req,url);
    if(p.startsWith('/api/depot/'))return this.depotUpload(req,p.slice(11),method);
    let body={},raw=null;
    if(p==='/api/files/upload'&&method==='POST'){raw=new Uint8Array(await req.arrayBuffer());}
    else if(method==='POST'||method==='PUT'){try{body=await req.json();}catch(e){body={};}}
    const auth=await this.storage.get('auth:pins');

    if(p==='/api/status'){const s=await this.session(req);return json({setup:!!auth,session:s?{role:s.role}:null,webauthn:!!(await this.storage.get('wa:creds')||[]).length});}

    // Installation : une seule fois, protégée par un code d'installation (hash SHA-256 connu du serveur)
    if(p==='/api/setup'&&method==='POST'){
      if(auth)return json({error:'Déjà installé'},409);
      const code=String(body.code||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
      const want=(this.env&&this.env.SETUP_CODE_SHA256)||SETUP_CODE_SHA256;
      if(!want||hex(await sha256(code))!==want){await this.registerFail();return json({error:'Code d\'installation incorrect'},403);}
      if(!/^\d{4,8}$/.test(String(body.ownerPin||''))||!/^\d{4,8}$/.test(String(body.managerPin||'')))return json({error:'PIN invalide (4 à 8 chiffres)'},400);
      await this.storage.put('auth:pins',{owner:await hashPin(String(body.ownerPin)),manager:await hashPin(String(body.managerPin))});
      let legacy={};
      try{ // reprise unique des données de l'ancien stockage JSONBin (fusionnées avec celles de l'appareil)
        if(typeof LEGACY_JSONBIN!=='undefined'&&LEGACY_JSONBIN.key){
          const r=await fetch('https://api.jsonbin.io/v3/b/'+LEGACY_JSONBIN.bin+'/latest',{headers:{'X-Master-Key':LEGACY_JSONBIN.key,'X-Bin-Meta':'false'}});
          if(r.ok){let d=await r.json();if(d&&d.gz){const bin=Uint8Array.from(atob(d.gz),c=>c.charCodeAt(0));d=JSON.parse(await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}legacy=d||{};}
        }
      }catch(e){legacy={};}
      const data=mergeDB(mergeDB({},legacy),body.data||{});await this.putData(data);
      await this.storage.put('auth:fails',{n:0,until:0});
      const token=await this.newSession('owner',body.label);
      return json({ok:true,token,role:'owner',data});
    }

    if(p==='/api/auth/pin'&&method==='POST'){
      if(!auth)return json({error:'Non installé',needSetup:true},409);
      const f=await this.lockState();
      if(f.until>Date.now())return json({error:'Trop d\'essais. Réessayez dans '+Math.ceil((f.until-Date.now())/60000)+' min (ou utilisez Face ID).',lockedUntil:f.until},429);
      const role=body.role==='manager'?'manager':'owner';
      if(await checkPin(String(body.pin||''),auth[role])){
        await this.storage.put('auth:fails',{n:0,until:0});
        return json({ok:true,role,token:await this.newSession(role,body.label)});
      }
      const nf=await this.registerFail();
      return json({error:'Code incorrect',fails:nf.n,lockedUntil:nf.until||0},401);
    }

    // WebAuthn — connexion (pas besoin de session)
    if(p==='/api/webauthn/login-options'&&method==='POST'){
      const creds=(await this.storage.get('wa:creds'))||[];
      const challenge=b64u(rand(32));await this.storage.put('wa:ch:'+challenge,{exp:Date.now()+180000,type:'get'});
      const ids=body.credId?[body.credId]:creds.map(c=>c.id);
      return json({challenge,rpId,allowCredentials:ids.map(id=>({type:'public-key',id})),userVerification:'required',timeout:60000});
    }
    if(p==='/api/webauthn/login'&&method==='POST'){
      const creds=(await this.storage.get('wa:creds'))||[];const cred=creds.find(c=>c.id===body.id);
      if(!cred)return json({error:'Face ID inconnu sur ce serveur — réactivez-le dans Paramètres'},404);
      const cdjB=unb64u(body.clientDataJSON||''),cdj=JSON.parse(dec.decode(cdjB));
      const ch=await this.storage.get('wa:ch:'+cdj.challenge);await this.storage.delete('wa:ch:'+cdj.challenge);
      if(!ch||ch.exp<Date.now()||ch.type!=='get'||cdj.type!=='webauthn.get'||cdj.origin!==origin)return json({error:'Défi expiré ou invalide'},400);
      const ad=unb64u(body.authenticatorData||''),pa=parseAuthData(ad);
      if(!eqBytes(pa.rpIdHash,await sha256(rpId))||!pa.up||!pa.uv)return json({error:'Vérification biométrique absente'},400);
      const ok=await verifySig(cred,concat(ad,await sha256(cdjB)),unb64u(body.signature||''));
      if(!ok)return json({error:'Signature Face ID invalide'},401);
      cred.lastUsed=Date.now();cred.signCount=pa.signCount;await this.storage.put('wa:creds',creds);
      await this.storage.put('auth:fails',{n:0,until:0});
      return json({ok:true,role:cred.role,token:await this.newSession(cred.role,body.label||cred.label)});
    }

    // Accès en lecture seule (banquier) : lien secret, expirant, révocable
    if(p==='/api/auth/share'&&method==='POST'){
      const t=String(body.token||'');if(t.length<20)return json({error:'Lien invalide'},400);
      const shares=[...(await this.storage.list({prefix:'share:'})).values()];
      const tb=enc.encode(t);const sh=shares.find(x=>{const xb=enc.encode(x.token||'');return xb.length===tb.length&&eqBytes(xb,tb);});
      if(!sh)return json({error:'Ce lien d\'accès n\'existe pas ou a été révoqué.'},403);
      if(sh.exp<Date.now())return json({error:'Ce lien d\'accès a expiré le '+new Date(sh.exp).toLocaleDateString('fr-FR')+'. Demandez-en un nouveau.'},403);
      sh.uses=(sh.uses||0)+1;sh.last=Date.now();await this.storage.put('share:'+sh.id,sh);
      const d=(await this.getData())||{};
      return json({ok:true,role:'viewer',token:await this.newSession('viewer',(body.label||'Lecture seule')+' · '+sh.label,{shareId:sh.id,hardExp:sh.exp,mask:sh.mask!==false}),exp:sh.exp,label:sh.label,owner:((d.settings||{}).nomProprietaire)||''});
    }

    if(p.startsWith('/api/f/')&&method==='GET'){
      const id=p.slice(7),k=url.searchParams.get('k')||'';
      const t=await this.storage.get('dl:'+k);
      if(!t||t.id!==id||t.exp<Date.now())return new Response('Lien expiré — rouvrez le document depuis l\'app.',{status:403,headers:{'Content-Type':'text/plain; charset=UTF-8'}});
      const m=await this.storage.get('fm:'+id);if(!m)return new Response('Document introuvable',{status:404});
      const out=new Uint8Array(m.size);let off=0;
      for(let i=0;i<m.chunks;i++){const c=new Uint8Array(await this.storage.get('fc:'+id+':'+i));out.set(c,off);off+=c.length;}
      const dl=url.searchParams.get('dl')==='1';
      return new Response(out,{headers:{'Content-Type':m.type||'application/octet-stream','Content-Disposition':(dl?'attachment':'inline')+'; filename*=UTF-8\'\''+encodeURIComponent(m.name),'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
    }

    // ── Tout ce qui suit exige une session
    const s=await this.session(req);
    if(!s)return json({error:'Session requise'},401);

    if(s.role==='viewer'){
      if(p==='/api/data'&&method==='GET'){const d=await this.getData();const meta=await this.storage.get('data:meta');return json({data:viewerData(d||{},s.mask!==false),rev:meta?meta.rev:0,readOnly:true});}
      if(p==='/api/logout'&&method==='POST'){await this.storage.delete('sess:'+s.key);return json({ok:true});}
      return json({error:'Accès en lecture seule'},403);
    }

    if(p.startsWith('/api/share/')){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      if(p==='/api/share/list'&&method==='GET'){
        const list=[...(await this.storage.list({prefix:'share:'})).values()].sort((a,b)=>b.created-a.created);
        return json({shares:list});
      }
      if(p==='/api/share/create'&&method==='POST'){
        const days=Math.max(1,Math.min(365,parseInt(body.days,10)||30));
        const sh={id:hex(rand(6)),token:b64u(rand(24)),label:String(body.label||'Banquier').slice(0,80),created:Date.now(),exp:Date.now()+days*86400000,mask:body.mask!==false,uses:0,last:null};
        await this.storage.put('share:'+sh.id,sh);return json({ok:true,share:sh});
      }
      if(p==='/api/share/revoke'&&method==='POST'){
        const id=String(body.id||'');await this.storage.delete('share:'+id);
        const keys=[...(await this.storage.list({prefix:'sess:'})).entries()].filter(([k,v])=>v.shareId===id).map(([k])=>k);
        if(keys.length)await this.storage.delete(keys);
        return json({ok:true,closed:keys.length});
      }
      return json({error:'Introuvable'},404);
    }

    if(p.startsWith('/api/mcp/')){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      const cfg=(await this.storage.get('mcp:cfg'))||{enabled:true};
      if(p==='/api/mcp/status'&&method==='GET'){const gr=[...(await this.storage.list({prefix:'mcpg:'})).entries()].map(([k,v])=>({id:k.slice(5),name:v.name,created:v.created,last:v.last,calls:v.calls||0}));return json({enabled:cfg.enabled!==false,url:origin+'/mcp',grants:gr});}
      if(p==='/api/mcp/config'&&method==='POST'){cfg.enabled=!!body.enabled;await this.storage.put('mcp:cfg',cfg);return json({ok:true,enabled:cfg.enabled});}
      if(p==='/api/mcp/revoke'&&method==='POST'){const all=!body.id;const keys=[];for(const pre of ['mcpa:','mcpr:']){for(const [k,v] of await this.storage.list({prefix:pre})){if(all||v.cid===body.id)keys.push(k);}}
        for(const [k] of await this.storage.list({prefix:'mcpg:'})){if(all||k==='mcpg:'+body.id)keys.push(k);}
        for(let i=0;i<keys.length;i+=100)await this.storage.delete(keys.slice(i,i+100));return json({ok:true,removed:keys.length});}
      return json({error:'Introuvable'},404);
    }

    if(p.startsWith('/api/mail/')){
      const cfg=(await this.storage.get('mail:cfg'))||null;
      const pub=c=>c?{configured:!!c.apiKey,keyHint:c.apiKey?('…'+c.apiKey.slice(-4)):'',senderEmail:c.senderEmail||'',senderName:c.senderName||'',replyTo:c.replyTo||'',bcc:!!c.bcc}:{configured:false};
      if(p==='/api/mail/config'&&method==='GET')return json(pub(cfg));
      if(p==='/api/mail/config'&&method==='POST'){
        if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
        if(body.clear){await this.storage.delete('mail:cfg');return json({configured:false});}
        const n=Object.assign({},cfg||{});
        if(body.apiKey)n.apiKey=String(body.apiKey).trim().slice(0,200);
        const em=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v||'').trim());
        if(body.senderEmail!==undefined){if(!em(body.senderEmail))return json({error:'Adresse d\'expéditeur invalide'},400);n.senderEmail=String(body.senderEmail).trim();}
        if(body.senderName!==undefined)n.senderName=String(body.senderName||'').slice(0,80);
        if(body.replyTo!==undefined)n.replyTo=em(body.replyTo)?String(body.replyTo).trim():'';
        if(body.bcc!==undefined)n.bcc=!!body.bcc;
        if(!n.apiKey||!n.senderEmail)return json({error:'Clé API et adresse d\'expéditeur requises'},400);
        await this.storage.put('mail:cfg',n);return json(pub(n));
      }
      if(p==='/api/mail/group'&&method==='POST'){
        if(!cfg||!cfg.apiKey)return json({error:'Envoi d\'e-mails non configuré (Paramètres)'},400);
        const seen={},to=(Array.isArray(body.to)?body.to:[]).map(x=>({email:String((x&&x.email)||'').trim(),name:String((x&&x.name)||'').slice(0,80)})).filter(x=>/^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(x.email)&&!seen[x.email.toLowerCase()]&&(seen[x.email.toLowerCase()]=1));
        if(!to.length)return json({error:'Aucun destinataire valide'},400);
        if(to.length>40)return json({error:'40 destinataires au maximum par envoi'},400);
        const subject=String(body.subject||'').trim().slice(0,200),text=String(body.text||'').trim().slice(0,20000);
        if(!subject||!text)return json({error:'Objet et message requis'},400);
        let sent=0;const failed=[];
        for(let i=0;i<to.length;i++){ // un message par locataire : aucune adresse n'est visible des autres
          const payload={sender:{email:cfg.senderEmail,name:cfg.senderName||cfg.senderEmail},to:[{email:to[i].email,name:to[i].name||undefined}],subject,textContent:text};
          if(cfg.replyTo)payload.replyTo={email:cfg.replyTo,name:cfg.senderName||undefined};
          if(cfg.bcc&&i===0)payload.bcc=[{email:cfg.replyTo||cfg.senderEmail}]; // une seule copie pour l'expéditeur
          try{const r=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{'api-key':cfg.apiKey,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});
            if(r.ok){sent++;await r.text();}else{let d={};try{d=JSON.parse(await r.text());}catch(e){}failed.push({email:to[i].email,error:'Brevo : '+(d.message||('erreur '+r.status))});}
          }catch(e){failed.push({email:to[i].email,error:'service e-mail injoignable'});}
        }
        return json({ok:true,sent,failed});
      }
      if(p==='/api/mail/send'&&method==='POST'){
        if(!cfg||!cfg.apiKey)return json({error:'Envoi d\'e-mails non configuré (Paramètres)'},400);
        const to=(Array.isArray(body.to)?body.to:[body.to]).map(x=>String(x||'').trim()).filter(x=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x)).slice(0,5);
        if(!to.length)return json({error:'Destinataire invalide'},400);
        const atts=(body.attachments||[]).slice(0,6).map(a=>({name:String(a.name||'document.pdf').replace(/[\\/:*?"<>|]+/g,'_').slice(0,120),content:String(a.content||'')})).filter(a=>a.content);
        let tot=0;atts.forEach(a=>tot+=a.content.length);if(tot>14000000)return json({error:'Pièces jointes trop volumineuses (10 Mo max)'},400);
        const payload={sender:{email:cfg.senderEmail,name:cfg.senderName||cfg.senderEmail},to:to.map((e,i)=>({email:e,name:i===0&&body.toName?String(body.toName).slice(0,80):undefined})),subject:String(body.subject||'Document').slice(0,200),textContent:String(body.text||' ').slice(0,20000)};
        if(cfg.replyTo)payload.replyTo={email:cfg.replyTo,name:cfg.senderName||undefined};
        if(cfg.bcc)payload.bcc=[{email:cfg.replyTo||cfg.senderEmail}];
        if(atts.length)payload.attachment=atts;
        let r,t;try{r=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{'api-key':cfg.apiKey,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});t=await r.text();}catch(e){return json({error:'Service e-mail injoignable'},502);}
        let d={};try{d=JSON.parse(t);}catch(e){}
        if(!r.ok)return json({error:'Brevo : '+(d.message||('erreur '+r.status))},502);
        return json({ok:true,id:d.messageId||''});
      }
      return json({error:'Introuvable'},404);
    }

    if(p==='/api/data'&&method==='GET'){const d=await this.getData();const meta=await this.storage.get('data:meta');return json({data:d||{},rev:meta?meta.rev:0});}
    if(p==='/api/data'&&method==='PUT'){
      const cur=(await this.getData())||{};const merged=mergeDB(cur,body.data||{});
      const same=JSON.stringify(merged)===JSON.stringify(cur);
      let rev;if(!same){rev=await this.putData(merged);}else{const m=await this.storage.get('data:meta');rev=m?m.rev:0;}
      this.state.waitUntil(this.backup());
      return json({ok:true,data:merged,rev,changed:!same});
    }
    if(p==='/api/auth/change-pin'&&method==='POST'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      if(!(await checkPin(String(body.oldPin||''),auth.owner)))return json({error:'Ancien code incorrect'},401);
      if(body.newOwner&&!/^\d{4,8}$/.test(body.newOwner))return json({error:'PIN propriétaire invalide'},400);
      if(body.newManager&&!/^\d{4,8}$/.test(body.newManager))return json({error:'PIN gestionnaire invalide'},400);
      if(body.newOwner)auth.owner=await hashPin(body.newOwner);
      if(body.newManager)auth.manager=await hashPin(body.newManager);
      await this.storage.put('auth:pins',auth);return json({ok:true});
    }
    if(p==='/api/webauthn/register-options'&&method==='POST'){
      const challenge=b64u(rand(32));await this.storage.put('wa:ch:'+challenge,{exp:Date.now()+180000,type:'create',role:s.role});
      const creds=(await this.storage.get('wa:creds'))||[];
      return json({challenge,rp:{name:'ImmoGest Pro',id:rpId},user:{id:b64u(enc.encode('immogest-'+s.role)),name:s.role==='owner'?'Propriétaire':'Gestionnaire',displayName:s.role==='owner'?'ImmoGest — Propriétaire':'ImmoGest — Gestionnaire'},
        pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},attestation:'none',timeout:60000,
        excludeCredentials:creds.filter(c=>c.role===s.role&&c.device===body.device).map(c=>({type:'public-key',id:c.id}))});
    }
    if(p==='/api/webauthn/register'&&method==='POST'){
      const cdjB=unb64u(body.clientDataJSON||''),cdj=JSON.parse(dec.decode(cdjB));
      const ch=await this.storage.get('wa:ch:'+cdj.challenge);await this.storage.delete('wa:ch:'+cdj.challenge);
      if(!ch||ch.exp<Date.now()||ch.type!=='create'||cdj.type!=='webauthn.create'||cdj.origin!==origin)return json({error:'Défi expiré ou invalide'},400);
      const att=cborDecode(unb64u(body.attestationObject||'')).value;const pa=parseAuthData(att.get('authData'));
      if(!eqBytes(pa.rpIdHash,await sha256(rpId))||!pa.uv||!pa.credId)return json({error:'Enregistrement Face ID invalide'},400);
      const key=await coseToKey(pa.cose);
      const creds=(await this.storage.get('wa:creds'))||[];const id=b64u(pa.credId);
      const rec={id,alg:key.alg,jwk:key.jwk,role:s.role,label:(body.label||'Appareil').slice(0,80),device:body.device||'',created:Date.now(),signCount:pa.signCount};
      const i=creds.findIndex(c=>c.id===id);if(i>=0)creds[i]=rec;else creds.push(rec);
      await this.storage.put('wa:creds',creds);return json({ok:true,id});
    }
    if(p==='/api/devices'&&method==='GET'){
      const list=[...(await this.storage.list({prefix:'sess:'})).entries()].map(([k,v])=>({id:k.slice(5,17),label:v.label,role:v.role,created:v.created,seen:v.seen,current:k==='sess:'+s.key}));
      const creds=((await this.storage.get('wa:creds'))||[]).map(c=>({id:c.id,label:c.label,role:c.role,created:c.created,lastUsed:c.lastUsed||null}));
      const meta=await this.storage.get('data:meta');const bks=[...(await this.storage.list({prefix:'bk:20'})).keys()].map(k=>k.slice(3));
      const mc=(await this.storage.get('mail:cfg'))||{};return json({sessions:list,faceid:creds,lastSave:meta?meta.at:null,backups:bks,mailBackup:(await this.storage.get('bkmail:last'))||null,filesBackup:(await this.storage.get('bkfiles:last'))||null,mailBackupTo:mc.apiKey?(mc.backupTo||mc.replyTo||mc.senderEmail||''):''});
    }
    if(p==='/api/devices/revoke'&&method==='POST'){
      if(s.role!=='owner'&&body.id!==s.key.slice(0,12))return json({error:'Réservé au propriétaire'},403);
      if(body.faceid){const creds=((await this.storage.get('wa:creds'))||[]).filter(c=>c.id!==body.faceid);await this.storage.put('wa:creds',creds);return json({ok:true});}
      const keys=[...(await this.storage.list({prefix:'sess:'})).keys()].filter(k=>k.slice(5,17)===body.id);await this.storage.delete(keys);return json({ok:true});
    }
    if(p==='/api/logout'&&method==='POST'){await this.storage.delete('sess:'+s.key);return json({ok:true});}
    if(p==='/api/backup/email'&&method==='POST'){if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);const r=await this.mailBackup('manuel');if(r.ok)r.documents=await this.mailFiles(8);return json(r,r.ok?200:400);}
    if(p==='/api/backup/restore'&&method==='POST'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      if(body.confirm!=='RESTAURER')return json({error:'Confirmation manquante'},400);
      let nd=body.data;
      if(!nd&&body.day){const gz=await this.storage.get('bk:'+body.day);if(!gz)return json({error:'Sauvegarde introuvable'},404);nd=JSON.parse(await new Response(new Blob([gz]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}
      try{const r=await this.restoreData(nd);return json(r);}catch(e){return json({error:e.message},400);}
    }
    if(p==='/api/backup'&&method==='GET'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      const day=url.searchParams.get('day');if(!day)return json({error:'jour requis'},400);
      const gz=await this.storage.get('bk:'+day);if(!gz)return json({error:'Sauvegarde introuvable'},404);
      const text=await new Response(new Blob([gz]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
      return new Response(text,{headers:{'Content-Type':'application/json','Content-Disposition':'attachment; filename="immogest_sauvegarde_'+day+'.json"','Cache-Control':'no-store'}});
    }
    // ── Documents (baux, états des lieux, pièces…) stockés dans le coffre, découpés en blocs de 1 Mo
    if(p==='/api/files/upload'&&method==='POST'){
      if(!raw||!raw.length)return json({error:'Fichier vide'},400);
      if(raw.length>25*1024*1024)return json({error:'Fichier trop lourd (25 Mo max)'},413);
      const h=k=>{try{return decodeURIComponent(req.headers.get(k)||'');}catch(e){return '';}};
      if(h('X-Cat')==='Photo'){
        if(!/^image\//.test(req.headers.get('Content-Type')||''))return json({error:'Une photo doit être une image'},415);
        if(raw.length>6*1024*1024)return json({error:'Photo trop lourde (6 Mo max)'},413);
        const lg=h('X-Log-Id').slice(0,60);if(!lg)return json({error:'Lot manquant'},400);
        const nb=[...(await this.storage.list({prefix:'fm:'})).values()].filter(m=>m.cat==='Photo'&&m.logId===lg).length;
        if(nb>=5)return json({error:'Maximum 5 photos par lot'},409);
      }
      const id='f'+hex(rand(9)),CH=1000000,chunks=Math.ceil(raw.length/CH);
      const meta={id,name:h('X-File-Name').slice(0,160)||'document',type:(req.headers.get('Content-Type')||'application/octet-stream').slice(0,100),size:raw.length,chunks,locId:h('X-Loc-Id').slice(0,60),logId:h('X-Log-Id').slice(0,60),batId:h('X-Bat-Id').slice(0,60),cat:h('X-Cat').slice(0,40)||'Autre',label:h('X-Label').slice(0,160),created:Date.now(),by:s.role};
      for(let i=0;i<chunks;i++)await this.storage.put('fc:'+id+':'+i,raw.slice(i*CH,(i+1)*CH).buffer);
      await this.storage.put('fm:'+id,meta);
      return json({ok:true,file:meta});
    }
    if(p==='/api/files'&&method==='GET'){
      const f={locId:url.searchParams.get('locId'),logId:url.searchParams.get('logId'),batId:url.searchParams.get('batId')};
      const list=[...(await this.storage.list({prefix:'fm:'})).values()].filter(m=>(!f.locId||m.locId===f.locId)&&(!f.logId||m.logId===f.logId)&&(!f.batId||m.batId===f.batId)).sort((a,b)=>b.created-a.created);
      return json({files:list});
    }
    if(p.startsWith('/api/files/')&&p.endsWith('/raw')&&method==='GET'){
      const id=p.slice(11,-4);const m=await this.storage.get('fm:'+id);if(!m)return json({error:'Document introuvable'},404);
      return new Response(await this.fileBytes(m),{headers:{'Content-Type':m.type||'application/octet-stream','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
    }
    if(p.startsWith('/api/files/')&&p.endsWith('/link')&&method==='POST'){
      const id=p.slice(11,-5);const m=await this.storage.get('fm:'+id);if(!m)return json({error:'Document introuvable'},404);
      const days=s.role==='owner'?Math.max(0,Math.min(365,parseInt(body.days,10)||0)):0;const k=b64u(rand(24));await this.storage.put('dl:'+k,{id,exp:Date.now()+(days?days*86400000:10*60000)});
      return json({url:'/api/f/'+id+'?k='+k});
    }
    if(p.startsWith('/api/files/')&&method==='DELETE'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      const id=p.slice(11);const m=await this.storage.get('fm:'+id);if(!m)return json({error:'Document introuvable'},404);
      const del=['fm:'+id];for(let i=0;i<m.chunks;i++)del.push('fc:'+id+':'+i);await this.storage.delete(del);
      return json({ok:true});
    }
    if(p.startsWith('/api/files/')&&method==='PATCH'){
      const id=p.slice(11);const m=await this.storage.get('fm:'+id);if(!m)return json({error:'Document introuvable'},404);
      let b={};try{b=await req.json();}catch(e){}
      if(b.cat)m.cat=String(b.cat).slice(0,40);if(b.name)m.name=String(b.name).slice(0,160);if(b.locId!==undefined)m.locId=String(b.locId).slice(0,60);if(b.ord!==undefined&&isFinite(+b.ord))m.ord=+b.ord;
      await this.storage.put('fm:'+id,m);return json({ok:true,file:m});
    }
    return json({error:'Introuvable'},404);
  }
}

function projCalc(S){
  S=S||{};var N=function(v){v=+v;return isFinite(v)?v:0;};
  var lots=S.lots||[],pcs=S.pcs||[];
  var surf=lots.reduce(function(a,x){return a+N(x.s);},0);
  var loyM=lots.reduce(function(a,x){return a+N(x.l);},0),loyA=loyM*12;
  var wLots=lots.reduce(function(a,x){return a+N(x.w);},0),wPc=pcs.reduce(function(a,x){return a+N(x.m);},0);
  var wBase=wLots+wPc,wImpr=wBase*N(S.impr)/100,wTot=wBase+wImpr;
  var notaire=N(S.prix)*N(S.notaire)/100,rev=N(S.prix)+notaire+wTot;
  var emp=Math.max(rev-N(S.apport),0),r=N(S.taux)/100/12,n=Math.round(N(S.duree)*12);
  var mens=(emp===0||n<=0)?0:(r===0?emp/n:emp*r/(1-Math.pow(1+r,-n)));
  var gestA=loyA*N(S.gest)/100,pno=N(S.pno),tf=N(S.tf);
  var cfA=loyA-mens*12-pno-tf-gestA;
  var vacA=loyA*N(S.vac)/100,entA=loyA*N(S.entr)/100,cfPrudA=cfA-vacA-entA;
  var noi=loyA-pno-tf-gestA,ann=mens*12;
  var dB=surf*N(S.dBas)-N(S.dFrais),dH=surf*N(S.dHaut)-N(S.dFrais),bloc=N(S.capi)>0?loyA/(N(S.capi)/100):0;
  var cible=N(S.cible)||10;
  return {surface:surf,loyers_mensuels:loyM,loyers_annuels:loyA,travaux_lots:wLots,travaux_communs:wPc,imprevus:wImpr,travaux_total:wTot,
    frais_notaire:notaire,prix_de_revient:rev,prix_de_revient_m2:surf?rev/surf:0,montant_emprunte:emp,apport:N(S.apport),mensualite:mens,annuite:ann,cash_flow_brut_an:loyA-ann,cash_flow_brut_mois:(loyA-ann)/12,
    gestion_an:gestA,pno_an:pno,tf_an:tf,cash_flow_an:cfA,cash_flow_mois:cfA/12,vacance_an:vacA,entretien_an:entA,cash_flow_prudent_an:cfPrudA,cash_flow_prudent_mois:cfPrudA/12,
    rendement_brut_pct:rev?loyA/rev*100:0,rendement_net_pct:rev?noi/rev*100:0,dscr:ann?noi/ann:null,
    rendement_cible_pct:cible,prix_achat_max_cible:Math.max(0,(loyA/(cible/100)-wTot)/(1+N(S.notaire)/100)),
    sortie_decoupe_bas:dB,sortie_decoupe_haut:dH,plus_value_decoupe_bas:dB-rev,plus_value_decoupe_haut:dH-rev,sortie_bloc:bloc,plus_value_bloc:bloc-rev};
}

