PdfDoc.prototype.wrapLines=function(s,size,maxW,bold){var out=[];pdfNorm(s).split('\n').forEach(function(par){var words=par.split(/\s+/),line='';words.forEach(function(w){var t=line?line+' '+w:w;if(pdfTW(t,size,bold)>maxW&&line){out.push(line);line=w;}else line=t;});out.push(line);});return out;};
PdfDoc.prototype.line=function(x1,y1,x2,y2,rgb,w){this.ops.push((rgb||'0.75 0.79 0.84')+' RG '+(w||0.8)+' w '+x1.toFixed(2)+' '+y1.toFixed(2)+' m '+x2.toFixed(2)+' '+y2.toFixed(2)+' l S');};
